<template>
  <view class="container">
    <!-- #ifndef MP-WEIXIN -->
    <!-- <custom-nav-bar title="我的"></custom-nav-bar> -->
    <!-- #endif -->


     <view class="bg">
      <image src="/static/images/22.png" mode="scaleToFill" class="bg-img" lazy-load></image>
    </view>


     <view class="info">
      <view class="text">八方远控 | 实况赛车热血越野 工程车</view>
      <view class="text">宿迁战神信息科技有限公司</view>
      <view class="text">Copyright © 2025-2026 All Rights Reserved</view>
    </view>

  </view>

  <BusinessModal v-model:visible="showModal" />

  <CustomModal
    v-model:visible="serviceModal"
    title="在线客服"
    :content="serviceTip"
    cancelText="拒绝"
    confirmText="允许"
    @confirm="handleConfirm"
  />
</template>

<script setup>
import { ref, computed } from "vue";
import { onPageShow } from "@dcloudio/uni-app";
import BusinessModal from "@/components/business-modal/business-modal.vue";
import CustomModal from "@/components/common-modal/common-modal.vue";
import { ChangeHeadImg } from "@/axios/mine";
import { GetUserInfo } from "@/axios/index";
import { useUserStore } from "@/store/modules/user";
import { baseUrl } from "@/config/env";

const userStore = useUserStore();
const imageUrl = ref("");

const userInfo = computed(() => userStore.userInfo);

const headShot = computed(() => {
  return userStore.headShot || 0;
});

const balance = computed(() => {
  return userStore.balance || 0;
});

const energy = computed(() => {
  return userStore.energy || 0;
});

const showModal = ref(false);
const serviceTip = ref("");
const serviceModal = ref(false);

const menuList = ref([
  // {
  //   name: "变更专区",
  //   icon: "/static/images/mine/icon_change@2x.png",
  //   key: "area",
  //   url: "/subpkg_mine/pages/mine/changeArea",
  // },
  // {
  //   name: "我的预约",
  //   icon: "/static/images/mine/icon_book@2x.png",
  //   key: "order",
  //   url: "/subpkg_mine/pages/mine/reservation",
  // },
  // {
  //   name: "我的申诉",
  //   icon: "/static/images/mine/icon_appeal@2x.png",
  //   key: "appeal",
  //   url: "/subpkg_mine/pages/mine/appeal",
  // },
  // {
  //   name: "驾驶记录",
  //   icon: "/static/images/mine/icon_record@2x.png",
  //   key: "record",
  //   url: "/subpkg_mine/pages/mine/driveRecord",
  // },
  // {
  //   name: "在线客服",
  //   icon: "/static/images/mine/icon_service@2x.png",
  //   key: "service",
  //   url: "",
  // },
  // {
  //   name: "商务合作",
  //   icon: "/static/images/mine/icon_cooperation@2x.png",
  //   key: "cooperation",
  //   url: "",
  // },
  {
    name: "设置",
    icon: "/static/images/mine/icon_set@2x.png",
    key: "set",
    url: "/subpkg_mine/pages/mine/set",
  },
]);

onPageShow(() => {
  GetUserInfo()
    .then((res) => {
      userStore.setUser(res.data);
      uni.removeStorageSync('new_user')
    })
    .catch(() => {});
});

const goPage = () => {
  uni.navigateTo({
    url: "/subpkg_mine/pages/mine/battery",
  });
};
const handleClick = (key, url) => {
  if (["area", "order", "appeal", "record", "set"].includes(key)) {
    uni.navigateTo({
      url,
    });
    return;
  }

  if (key == "cooperation") {
    showModal.value = true;
    return;
  }

  if (key == "service") {
    // #ifdef MP-TOUTIAO
    serviceTip.value = "是否打开抖音在线客服";
    // #endif

    // #ifdef MP-WEIXIN || H5
    serviceTip.value = "是否打开微信，联系在线客服";
    // #endif

    serviceModal.value = true;
  }
};
const handleConfirm = () => {
  openService();
};
const openService = () => {
  // ======================================
  // 1. 微信小程序 → 官方客服（最稳定）
  // ======================================
  // #ifdef MP-WEIXIN
  wx.openCustomerServiceChat({
    extInfo: {
      url: "https://work.weixin.qq.com/kfid/kfc01ee6e218344d59f", // 必须是后台已配置的 HTTPS 客服链接
    },
    corpId: "wwc2e2dca3bf58025c",
    success: () => {},
    fail: (e) => {
      console.log("客服", e);
      uni.showToast({
        title: "客服暂时不可用",
        icon: "none",
      });
    },
  });
  // #endif

  // ======================================
  // 2. 抖音小程序 → 官方IM客服
  // ======================================
  // #ifdef MP-TOUTIAO
  tt.openCustomerServiceConversation({
    success: () => {},
    fail: () => {
      uni.showToast({
        title: "客服暂时不可用",
        icon: "none",
      });
    },
  });
  // #endif

  // ======================================
  // 3. H5 / App → 打开微信客服链接
  // ======================================
  // #ifndef MP-WEIXIN || MP-TOUTIAO
  uni.showModal({
    title: "联系客服",
    content: "微信：we1731747901",
    confirmText: "复制微信",
    success: (res) => {
      if (res.confirm) {
        uni.setClipboardData({
          data: "we1731747901",
          success: () => {
            uni.showToast({
              title: "复制成功",
            });
          },
        });
      }
    },
  });
  // #endif
};

const gotoProfile = () => {
  uni.navigateTo({
    url: "/subpkg_mine/pages/mine/editProfile",
  });
};

// 选择并上传图片（兼容微信/抖音小程序）
const changeHeader = () => {
  // 选择图片（限制 1 张）
  uni
    .chooseImage({
      count: 1,
      sizeType: ["compressed"],
      sourceType: ["album"],
    })
    .then((res) => {
      const tempFilePath = res.tempFilePaths[0];
      // 校验大小 1M
      return uni.getFileInfo({ filePath: tempFilePath }).then((fileInfo) => {
        const sizeMB = fileInfo.size / (1024 * 1024);
        if (sizeMB > 1) {
          uni.showToast({ title: "图片大小不能超过1M", icon: "none" });
          // 返回一个被拒绝的 Promise 来中断后续链式调用
          return Promise.reject("图片过大");
        }
        // 图片校验通过，继续上传
        return uploadFile(tempFilePath);
      });
    })
    .catch((err) => {
      // 统一处理错误，包括用户取消选择、图片过大等
      if (err !== "图片过大") {
        console.error("选择图片失败：", err);
      }
    });
};

// 上传文件（已修复 BUG）
const uploadFile = async (filePath) => {
  uni.showLoading({ title: "上传中..." });

  // 上传前先清空旧图，防止显示错误
  imageUrl.value = "";

  try {
    const uploadRes = await uni.uploadFile({
      url: baseUrl + "/api/upload/picture",
      filePath: filePath,
      name: "imageFile[]", // 修复：只保留一个
      method: "POST",
    });

    const data = JSON.parse(uploadRes.data);
    console.log(data);
    if (data.code === 200) {
      // 上传成功 → 赋值展示
      imageUrl.value = data.data.file[0];
      ChangeHeadImg({ head_shot: imageUrl.value }).then((res) => {
        if (data.code === 200) {
          uni.showToast({ title: "上传成功", icon: "success" });
          userStore.setHeadImg(imageUrl.value);
        }
      });
    } else {
      throw new Error("上传失败");
    }
  } catch (err) {
    imageUrl.value = ""; // 失败清空
    uni.showToast({ title: "上传失败", icon: "none" });
    console.error("上传错误：", err);
  } finally {
    uni.hideLoading();
  }
};

const gotoUrl = () => {
  uni.reLaunch({
    url: "/subpkg_login/pages/login/index",
  });
};
</script>

<style lang="scss" scoped>
