      text-align: center;
      font-size: 20rpx;
      color: #999;
      font-family:
        Regular,
        PingFangSC,
        PingFang SC;
    }
  }
}

.bg-image {
  position: absolute;
  z-index: 0;
  height: 530rpx;
  width: 100%;

  background: linear-gradient(180deg, #A8D4F5 0%, #D6ECFF 100%);

  .image {
    width: 100%;
    height: 400rpx;
    display: block;
  }
}

/* 顶部区域 */
.header {
  position: relative;
  z-index: 1;
  top: 150rpx;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 20rpx 30rpx;
  height: 100rpx;
}

